14	/// Complete the given command, shell-agnostic
15	pub fn complete(
16	    cmd: &mut clap::Command,
17	    args: Vec<OsString>,
18	    arg_index: usize,
19	    current_dir: Option<&std::path::Path>,
20	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
21	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
22	    cmd.build();
23	
24	    let raw_args = clap_lex::RawArgs::new(args);
25	    let mut cursor = raw_args.cursor();
26	    let mut target_cursor = raw_args.cursor();
27	    raw_args.seek(
28	        &mut target_cursor,
29	        clap_lex::SeekFrom::Start(arg_index as u64),
30	    );
31	    // As we loop, `cursor` will always be pointing to the next item
32	    raw_args.next_os(&mut target_cursor);
33	    debug!("complete: target_cursor={target_cursor:?}");
34	
35	    // TODO: Multicall support
36	    if !cmd.is_no_binary_name_set() {
37	        raw_args.next_os(&mut cursor);
38	    }
39	
40	    let mut current_cmd = &*cmd;
41	    let mut pos_index = 1;
42	    let mut is_escaped = false;
43	    let mut next_state = ParseState::ValueDone;
44	    let mut used_args = Vec::<clap::Id>::new();
45	    while let Some(arg) = raw_args.next(&mut cursor) {
46	        let current_state = next_state;
47	        next_state = ParseState::ValueDone;
48	        debug!(
49	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
50	            arg.to_value_os(),
51	        );
52	        if cursor == target_cursor {
53	            return complete_arg(
54	                &arg,
55	                current_cmd,
56	                current_dir,
57	                pos_index,
58	                is_escaped,
59	                current_state,
60	                &used_args,
61	            );
62	        }
63	
64	        if !is_escaped && !matches!(current_state, ParseState::Opt(..) | ParseState::Pos(..)) {
65	            if let Ok(value) = arg.to_value() {
66	                if let Some(next_cmd) = current_cmd.find_subcommand(value) {
67	                    current_cmd = next_cmd;
68	                    pos_index = 1;
69	                    used_args.clear();
70	                    continue;
71	                }
72	            }
73	        }
74	
75	        if is_escaped {
76	            (next_state, pos_index) =
77	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
78	        } else if arg.is_escape() {
79	            is_escaped = true;
80	            // Like the parser, `--` jumps straight to a `last(true)`
81	            // positional, skipping any unfilled positionals.
82	            if let Some(last_index) = current_cmd
83	                .get_positionals()
84	                .filter(|p| p.is_last_set())
85	                .filter_map(|p| p.get_index())
86	                .max()
87	            {
88	                pos_index = last_index;
89	            }
90	        } else if opt_allows_hyphen(&current_state, &arg) {
91	            match current_state {
92	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
93	                _ => unreachable!("else branch is only reachable in Opt state"),
94	            }
95	        } else if let Some((flag, value)) = arg.to_long() {
96	            if let Ok(flag) = flag {
97	                let opt = current_cmd.get_arguments().find(|a| is_long_match(a, flag));
98	
99	                if let Some(opt) = opt {
100	                    record_used_arg(&mut used_args, opt.get_id());
101	                    if opt.get_num_args().expect("built").takes_values() {
102	                        // An attached value (`--opt=value`) counts toward the
103	                        // option's values just like a space-separated one, so
104	                        // that completing after `--opt=value` sees the same
105	                        // state as completing after `--opt value`.
106	                        // An empty attached value (`--opt=`) types no value
107	                        // yet, so the option stays pending.
108	                        let count = value
109	                            .filter(|v| !v.is_empty())
110	                            .map(|v| attached_value_count(opt, v))
111	                            .unwrap_or(0);
112	                        next_state = parse_opt_value(opt, count);
113	                    };
114	                } else if pos_allows_hyphen(current_cmd, pos_index) {
115	                    (next_state, pos_index) =
116	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
117	                }
118	            }
119	        } else if let Some(short) = arg.to_short() {
120	            let (_, matched_opts, takes_value_opt, mut short) =
121	                parse_shortflags(current_cmd, short);
122	            for opt in &matched_opts {
123	                record_used_arg(&mut used_args, opt.get_id());
124	            }
125	            if let Some(opt) = takes_value_opt {
126	                // An attached value (`-ovalue`, `-o=value`) counts toward the
127	                // option's values just like a space-separated one. An empty
128	                // attached value (`-o=`) types no value yet, so the option
129	                // stays pending instead of being treated as satisfied.
130	                let count = short
131	                    .next_value_os()
132	                    .map(|v| v.strip_prefix("=").unwrap_or(v))
133	                    .filter(|v| !v.is_empty())
134	                    .map(|v| attached_value_count(opt, v))
135	                    .unwrap_or(0);
136	                next_state = parse_opt_value(opt, count);
137	            } else if pos_allows_hyphen(current_cmd, pos_index) {
138	                (next_state, pos_index) =
139	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
140	            }
141	        } else {
142	            match current_state {
143	                ParseState::ValueDone | ParseState::Pos(..) => {
144	                    (next_state, pos_index) =
145	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
146	                }
147	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
148	            }
149	        }
150	    }
151	
152	    Err(std::io::Error::other("no completion generated"))
153	}
154	
155	#[derive(Debug, PartialEq, Eq, Clone)]
156	enum ParseState<'a> {
157	    /// Parsing a value done, there is no state to record.
158	    ValueDone,
159	
160	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
161	    Pos((usize, usize)),
162	
163	    /// Parsing a optional flag argument
164	    Opt((&'a clap::Arg, usize)),
165	}
166	
167	fn complete_arg(
168	    arg: &clap_lex::ParsedArg<'_>,
169	    cmd: &clap::Command,
170	    current_dir: Option<&std::path::Path>,
171	    pos_index: usize,
172	    is_escaped: bool,
173	    state: ParseState<'_>,
174	    used_args: &[clap::Id],
175	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
176	    debug!(
177	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
178	        arg,
179	        cmd.get_name(),
180	        current_dir,
181	        pos_index,
182	        state
183	    );
184	    let mut completions = Vec::<CompletionCandidate>::new();
185	
186	    match state {
187	        ParseState::ValueDone => {
188	            if !is_escaped {
189	                if let Ok(value) = arg.to_value() {
190	                    completions.extend(complete_subcommand(value, cmd));
191	                }
192	            }
193	
194	            if let Some(positional) = find_positional(cmd, pos_index, is_escaped) {
195	                completions.extend(complete_arg_value(
196	                    arg.to_value(),
197	                    positional,
198	                    current_dir,
199	                    0,
200	                ));
201	            }
202	            if !is_escaped {
203	                completions.extend(complete_option(arg, cmd, current_dir));
204	            }
205	        }
206	        ParseState::Pos((_, num_arg)) => {
207	            if let Some(positional) = find_positional(cmd, pos_index, is_escaped) {
208	                completions.extend(complete_arg_value(
209	                    arg.to_value(),
210	                    positional,
211	                    current_dir,
212	                    num_arg.saturating_sub(1),
213	                ));
214	                if !is_escaped
215	                    && positional
216	                        .get_num_args()
217	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
218	                {
219	                    completions.extend(complete_option(arg, cmd, current_dir));
220	                }
221	            }
222	        }
223	        ParseState::Opt((opt, count)) => {
224	            completions.extend(complete_arg_value(
225	                arg.to_value(),
226	                opt,
227	                current_dir,
228	                count.saturating_sub(1),
229	            ));
230	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
231	            if count > min && can_switch_to_other_arg(opt, arg) {
232	                // The option's required values are satisfied and this word
233	                // would be parsed as a new flag rather than another value, so
234	                // also complete it as a positional, flag, option or subcommand.
235	                completions.extend(complete_arg(
236	                    arg,
237	                    cmd,
238	                    current_dir,
239	                    pos_index,
240	                    is_escaped,
241	                    ParseState::ValueDone,
242	                    used_args,
243	                )?);
244	            }
245	        }
246	    }
247	    filter_unavailable_args(&mut completions, cmd, used_args);
248	    if completions.iter().any(|a| !a.is_hide_set()) {
249	        completions.retain(|a| !a.is_hide_set());
250	    }
251	    dedup_argument_candidates(&mut completions, arg.is_empty());
252	
253	    let mut tags = Vec::new();
254	    for candidate in &completions {
255	        let tag = candidate.get_tag().cloned();
256	        if !tags.contains(&tag) {
257	            tags.push(tag);
258	        }
259	    }
260	    completions.sort_by_key(|c| {
261	        (
262	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
263	            c.get_display_order(),
264	        )
265	    });
266	
267	    Ok(completions)
268	}
269	
270	fn complete_option(
271	    arg: &clap_lex::ParsedArg<'_>,
272	    cmd: &clap::Command,
273	    current_dir: Option<&std::path::Path>,
274	) -> Vec<CompletionCandidate> {
275	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
276	    let mut completions = Vec::<CompletionCandidate>::new();
277	    if arg.is_empty() {
278	        completions.extend(longs_and_visible_aliases(cmd));
279	        completions.extend(hidden_longs_aliases(cmd));
280	
281	        let dash_or_arg = if arg.is_empty() {
282	            "-".into()
283	        } else {
284	            arg.to_value_os().to_string_lossy()
285	        };
286	        completions.extend(
287	            shorts_and_visible_aliases(cmd)
288	                .into_iter()
289	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
290	        );
291	    } else if arg.is_stdio() {
292	        // HACK: Assuming knowledge of is_stdio
293	        let dash_or_arg = if arg.is_empty() {
294	            "-".into()
295	        } else {
296	            arg.to_value_os().to_string_lossy()
297	        };
298	        completions.extend(
299	            shorts_and_visible_aliases(cmd)
300	                .into_iter()
301	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
302	        );
303	
304	        completions.extend(longs_and_visible_aliases(cmd));
305	        completions.extend(hidden_longs_aliases(cmd));
306	    } else if arg.is_escape() {
307	        // HACK: Assuming knowledge of is_escape
308	        completions.extend(longs_and_visible_aliases(cmd));
309	        completions.extend(hidden_longs_aliases(cmd));
310	    } else if let Some((flag, value)) = arg.to_long() {
311	        if let Ok(flag) = flag {
312	            if let Some(value) = value {
313	                if let Some(arg) = cmd.get_arguments().find(|a| is_long_match(a, flag)) {
314	                    completions.extend(
315	                        complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
316	                            .into_iter()
317	                            .map(|comp| comp.add_prefix(format!("--{flag}="))),
318	                    );
319	                }
320	            } else {
321	                completions.extend(
322	                    longs_and_visible_aliases(cmd)
323	                        .into_iter()
324	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
325	                );
326	                completions.extend(
327	                    hidden_longs_aliases(cmd)
328	                        .into_iter()
329	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
330	                );
331	            }
332	        }
333	    } else if let Some(short) = arg.to_short() {
334	        if !short.is_negative_number() {
335	            // Find the first takes_values option.
336	            let (leading_flags, _, takes_value_opt, mut short) = parse_shortflags(cmd, short);
337	
338	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
339	            if let Some(opt) = takes_value_opt {
340	                let mut peek_short = short.clone();
341	                let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
342	                    short.next_flag();
343	                    true
344	                } else {
345	                    false
346	                };
347	
348	                let value = short.next_value_os().unwrap_or(OsStr::new(""));
349	                completions.extend(
350	                    complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
351	                        .into_iter()
352	                        .map(|comp| {
353	                            let sep = if has_equal { "=" } else { "" };
354	                            comp.add_prefix(format!("-{leading_flags}{sep}"))
355	                        }),
356	                );
357	            } else {
358	                completions.extend(
359	                    shorts_and_visible_aliases(cmd)
360	                        .into_iter()
361	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
362	                );
363	            }
364	        }
365	    }
366	    debug!("complete_option: completions={completions:?}");
367	    completions
368	}
369	
370	fn complete_arg_value(
371	    value: Result<&str, &OsStr>,
372	    arg: &clap::Arg,
373	    current_dir: Option<&std::path::Path>,
374	    arg_index: usize,
375	) -> Vec<CompletionCandidate> {
376	    let mut values = Vec::new();
377	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
378	
379	    let (prefix, value) =
380	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
381	
382	    let value_os = match value {
383	        Ok(value) => OsStr::new(value),
384	        Err(value_os) => value_os,
385	    };
386	
387	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
388	        values.extend(completer.complete_at(arg_index, value_os));
389	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
390	        values.extend(complete_value_candidates(
391	            value_os,
392	            completer.value_candidates(),
393	        ));
394	    } else if let Some(possible_values) = possible_values(arg) {
395	        if let Ok(value) = value {
396	            values.extend(complete_candidates_str(
397	                value,
398	                possible_value_candidates(possible_values),
399	            ));
400	        }
401	    } else {
402	        match arg.get_value_hint() {
403	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
404	                // Should not complete
405	            }
406	            clap::ValueHint::AnyPath => {
407	                values.extend(complete_path(value_os, current_dir, &|_| true));
408	            }
409	            clap::ValueHint::FilePath => {
410	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
411	            }
412	            clap::ValueHint::DirPath => {
413	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
414	            }
415	            clap::ValueHint::ExecutablePath => {
416	                use is_executable::IsExecutable;
417	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
418	            }
419	            clap::ValueHint::CommandName
420	            | clap::ValueHint::CommandString
421	            | clap::ValueHint::CommandWithArguments
422	            | clap::ValueHint::Username
423	            | clap::ValueHint::Hostname
424	            | clap::ValueHint::Url
425	            | clap::ValueHint::EmailAddress => {
426	                // No completion implementation
427	            }
428	            _ => {
429	                // Safe-ish fallback
430	                values.extend(complete_path(value_os, current_dir, &|_| true));
431	            }
432	        }
433	
434	        values.sort();
435	    }
436	
437	    if let Some(prefix) = prefix {
438	        values = values
439	            .into_iter()
440	            .map(|comp| comp.add_prefix(prefix))
441	            .collect();
442	    }
443	    values = values
444	        .into_iter()
445	        .map(|comp| {
446	            if comp.get_tag().is_some() {
447	                comp
448	            } else {
449	                comp.tag(Some(arg.to_string().into()))
450	            }
451	        })
452	        .collect();
453	
454	    debug!("complete_arg_value: values={values:?}");
455	    values
456	}
457	
458	fn rsplit_delimiter<'s, 'o>(
459	    value: Result<&'s str, &'o OsStr>,
460	    delimiter: Option<char>,
461	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
462	    let delimiter = delimiter?;
463	    let value = value.ok()?;
464	    let pos = value.rfind(delimiter)?;
465	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
466	    Some((Some(prefix), Ok(value)))
467	}
468	
469	fn complete_value_candidates(
470	    value: &OsStr,
471	    completer: &dyn ValueCandidates,
472	) -> Vec<CompletionCandidate> {
473	    debug!("complete_value_candidates: value={value:?}");
474	
475	    let mut values = completer.candidates();
476	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
477	    values
478	}
479	
480	fn complete_candidates_str(
481	    value: &str,
482	    mut values: Vec<CompletionCandidate>,
483	) -> Vec<CompletionCandidate> {
484	    debug!("complete_candidates_str: value={value:?}");
485	
486	    values.retain(|comp| comp.get_value().starts_with(value));
487	    values
488	}
489	
490	fn complete_value_candidates_str(
491	    value: &str,
492	    completer: &dyn ValueCandidates,
493	) -> Vec<CompletionCandidate> {
494	    debug!("complete_value_candidates_str: value={value:?}");
495	
496	    complete_candidates_str(value, completer.candidates())
497	}
498	
499	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
500	    debug!(
501	        "complete_subcommand: cmd={:?}, value={:?}",
502	        cmd.get_name(),
503	        value
504	    );
505	
506	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
507	        .into_iter()
508	        .filter(|x| x.get_value().starts_with(value))
509	        .collect();
510	    if cmd.is_allow_external_subcommands_set() {
511	        let external_completer = cmd.get::<SubcommandCandidates>();
512	        if let Some(completer) = external_completer {
513	            scs.extend(complete_value_candidates_str(
514	                value,
515	                completer.value_candidates(),
516	            ));
517	        }
518	    }
519	
520	    scs.dedup();
521	    scs
522	}
