use clap::{Arg, ArgAction, Command};
use clap_complete::engine::{ArgValueCandidates, CompletionCandidate};

fn define_tool_cmd() -> Command {
    Command::new("tool").disable_help_flag(true).disable_version_flag(true).disable_help_subcommand(true)
        .arg(Arg::new("define").long("define").action(ArgAction::Append).num_args(1..)
            .allow_hyphen_values(true).value_terminator(";")
            .add(ArgValueCandidates::new(|| vec![CompletionCandidate::new("name="), CompletionCandidate::new("path=")])))
        .arg(Arg::new("verbose").long("verbose").action(ArgAction::SetTrue))
        .arg(Arg::new("path").value_parser(["src", "dst"]))
        .subcommand(Command::new("run").disable_help_flag(true).disable_version_flag(true).disable_help_subcommand(true)
            .arg(Arg::new("define").long("define").action(ArgAction::Append).num_args(1..)
                .allow_hyphen_values(true).value_terminator(";")
                .add(ArgValueCandidates::new(|| vec![CompletionCandidate::new("job="), CompletionCandidate::new("log=")])))
            .arg(Arg::new("target").value_parser(["test", "bench"])))
}

