    let mut cmd = define_tool_cmd();
    let a: Vec<_> = args.iter().map(|s| std::ffi::OsString::from(*s)).collect();
    let i = a.len() - 1;
    clap_complete::engine::complete(&mut cmd, a, i, None).unwrap()
        .into_iter().map(|c| c.get_value().to_string_lossy().into_owned()).collect()
}

